```typescript
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Cause: We need controlled dependencies. Effect: Predictable tests.
const mockCartContext = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn(),
};

const mockPaymentContext = {
  processPayment: vi.fn(),
};

const renderCheckout = (props = {}) => {
  return render(
    <CartProvider value={mockCartContext}>
      <PaymentProvider value={mockPaymentContext}>
        <Checkout {...props} />
      </PaymentProvider>
    </CartProvider>
  );
};

describe('Checkout - The Causality Chain', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockPaymentContext.processPayment.mockResolvedValue({ orderId: 'ORD-12345' });
  });

  describe('Happy Path - The Inevitable Flow', () => {
    it('completes full checkout when all causes align', async () => {
      const user = userEvent.setup();
      const onComplete = vi.fn();
      renderCheckout({ onComplete });

      // Shipping step
      await user.type(screen.getByLabelText(/street address/i), '123 Matrix Lane');
      await user.type(screen.getByLabelText(/city/i), 'Zion');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Payment step
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Neo Anderson');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Review step
      expect(screen.getByText(/123 matrix lane/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-12345');
    });
  });

  describe('Validation - Consequences of Incompleteness', () => {
    it('displays shipping errors when required fields empty', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('rejects invalid ZIP format', async () => {
      const user = userEvent.setup();
      renderCheckout();

      await user.type(screen.getByLabelText(/zip code/i), 'WRONG');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  describe('Edge Cases - The Anomalies', () => {
    it('shows empty cart message when cart has no items', () => {
      mockCartContext.items = [];
      renderCheckout();

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure gracefully', async () => {
      mockPaymentContext.processPayment.mockRejectedValue(new Error('Card declined'));
      // ... navigate to review, click place order

      await waitFor(() => {
        expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
      });
    });
  });

  describe('Accessibility - No One Left Behind', () => {
    it('has no accessibility violations', async () => {
      const { container } = renderCheckout();
      expect(await axe(container)).toHaveNoViolations();
    });
  });
});
